parameters.jsCode:
// Body: { e_sorder_id, writer,
//   header?: { ship_via, ship_branch, ship_date, required_date, shipping_instructions, internal_notes },
//   lines: [{ line_id?, productId, quantity, unitPrice?, original_price?, comments?, ship_branch? }],
//   custom_lines?: [{ name, ideal_sku, quantity, unit_price, variation_of, customizations, ship_branch? }],
//   order_status? }
// `lines` is the complete list the open generation's lines should end up
// as. A line_id is an existing Eclipse line, no line_id is a new line, and
// existing lines left out are deleted. comments on an existing line is
// added to it by re-creating the line (Eclipse cannot edit a line's
// comments). ship_branch: the branch the line ships from; a line on
// another branch moves to that branch's generation (2026-10-19).
// header: only the fields sent change. Ship branch and required date
// cannot be changed on a generation in Eclipse, so a change there moves the
// lines to a generation that has them (Plan).
// custom_lines: new custom lines, as product 15680 ("ITEM:") with their text
// in the line comment, the same as create-order.
// order_status (Convert to Order): after the changes, every bid generation
// of the order gets this status.
// original_price (new lines only, 2026-10-29): the price before the rep
// changed it, for price_change_record on the HubSpot line item.
const CUSTOM_PRODUCT_ID = 15680;
const STATUSES = ['ShipWhenComplete', 'ShipWhenAvailable', 'ShipWhenSpecified', 'ShipItemComplete', 'Direct',
  'CallWhenAvailable', 'CallWhenComplete', 'CallWhenSpecified', 'PickUpNow', 'ShipTicket'];
const parseId = (raw) => {
  const m = String(raw || '').trim().toUpperCase().match(/^S?(\d+)(?:\.(\d{1,4}))?$/);
  if (!m) return null;
  const oid = 'S' + m[1];
  const genId = String(Number(m[2] || 1));
  return { oid, genId, eSorderId: oid + '.' + genId.padStart(4, '0') };
};
const branchOf = (v) => { const m = String(v == null ? '' : v).trim().match(/^(\d+)/); return m ? m[1] : ''; };
const isoDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? String(v) : '';
const text = (v) => (v == null ? null : String(v));
const b = $input.first().json.body || {};
const fail = (msg) => [{ json: { ok: false, statusCode: 400, body: { success: false, error: msg, step: 'validate' } } }];
const id = parseId(b.e_sorder_id);
if (!id) return fail('Missing or invalid e_sorder_id (expected S1234567.0001).');
if (!b.writer) return fail('Missing writer (e_user_id)');
const h = b.header && typeof b.header === 'object' ? b.header : {};
// null = not sent, leave Eclipse's value.
const header = {
  shipVia: h.ship_via == null ? null : String(h.ship_via).trim(),
  shipBranch: branchOf(h.ship_branch) || null,
  shipDate: isoDate(h.ship_date) || null,
  requiredDate: isoDate(h.required_date) || null,
  shippingInstructions: text(h.shipping_instructions),
  internalNotes: text(h.internal_notes),
};
if (header.shipDate && header.requiredDate && header.requiredDate < header.shipDate) return fail('Required date cannot be before ship date.');
const lines = (Array.isArray(b.lines) ? b.lines : []).map((l) => ({
  lineId: l.line_id != null && l.line_id !== '' ? Number(l.line_id) : null,
  productId: Number(l.productId),
  quantity: Math.round(Number(l.quantity) || 0),
  unitPrice: l.unitPrice != null && l.unitPrice !== '' && isFinite(Number(l.unitPrice)) ? Number(l.unitPrice) : null,
  originalPrice: l.original_price != null && l.original_price !== '' && isFinite(Number(l.original_price)) ? Number(l.original_price) : null,
  comments: String(l.comments == null ? '' : l.comments).trim(),
  branch: branchOf(l.ship_branch),
})).filter((l) => l.productId && l.quantity > 0);
// Same comment text as create-order's custom lines.
const customComment = (c) => {
  const out = ["Suggested name: '" + String(c.name || '').trim() + "'"];
  const v = c.variation_of;
  if (v && v.product_id) out.push("Variation of product: '." + String(v.product_id).trim() + "'");
  if (String(c.ideal_sku || '').trim()) out.push('SKU: ' + String(c.ideal_sku).trim());
  if (v && v.product_id && v.serial_number) out.push('SN: ' + String(v.serial_number).trim());
  for (const x of (Array.isArray(c.customizations) ? c.customizations : [])) if (String(x).trim()) out.push(String(x).trim());
  return out.filter(Boolean).join('\n');
};
for (const c of (Array.isArray(b.custom_lines) ? b.custom_lines : [])) {
  const qty = Math.round(Number(c.quantity) || 0);
  const comments = customComment(c);
  if (!(qty > 0) || !String(c.name || '').trim()) continue;
  lines.push({
    lineId: null, productId: CUSTOM_PRODUCT_ID, quantity: qty,
    unitPrice: c.unit_price != null && c.unit_price !== '' && isFinite(Number(c.unit_price)) ? Number(c.unit_price) : 0,
    comments, branch: branchOf(c.ship_branch), custom: true,
  });
}
if (!lines.length) return fail('A bid needs at least one line. Cancel the bid to remove it.');
const orderStatus = b.order_status ? String(b.order_status) : '';
if (orderStatus && !STATUSES.includes(orderStatus)) return fail('Unknown order status "' + orderStatus + '".');
return [{ json: { ok: true, ...id, writer: String(b.writer).toUpperCase(), header, lines, orderStatus } }];

// Diff the request against the bid as Eclipse has it now.
// Lines live on a generation, and a generation has one ship branch and one
// required date that Eclipse cannot change. So each line goes to the
// generation for its ship branch with the wanted required date: the open
// one when those still match, else another bid generation of this order
// that matches, else a new one (Create Shipment, as v1 did). A line that
// changes generation, or gets a comment, is re-created there (POST) and
// deleted where it was. The open generation is cancelled when no line is
// left on it. Emits one item per generation to create (for Create
// Shipment), or one { create: false } item; the plan rides on the first.
const v = $('Validate').first().json;
const env = $input.first().json;
const fail = (statusCode, error, step) => [{ json: { ok: false, statusCode, body: { success: false, error, step } } }];
if (env.error) return fail(502, 'Eclipse GET /SalesOrders?id=' + v.oid + ' failed: ' + env.error + ' ' + JSON.stringify(env.message || '').substring(0, 500), 'getSalesOrder');
const so = (Array.isArray(env.results) ? env.results[0] : env) || {};
if (!Array.isArray(so.generations) || !so.generations.length) return fail(404, 'Eclipse order ' + v.oid + ' not found.', 'getSalesOrder');
const gidOf = (g) => String(Number(g.generationId));
const gen = so.generations.find((g) => gidOf(g) === v.genId);
if (!gen) return fail(404, 'Order ' + v.oid + ' has no generation ' + v.genId + '.', 'getSalesOrder');
const status = String(gen.status || '');
if (status !== 'Bid') return fail(409, 'Order ' + v.eSorderId + ' is ' + (status || 'not a bid') + ', not a Bid. Only bids can be edited.', 'plan');
const day = (d) => String(d || '').slice(0, 10);
const branchOf = (x) => { const m = String(x == null ? '' : x).trim().match(/^(\d+)/); return m ? m[1] : ''; };
const trim = (s) => String(s == null ? '' : s).trim();

// The open generation's header, and what the rep wants it to be.
const cur = {
  branch: branchOf(gen.shipBranch), requiredDate: day(gen.requiredDate), shipDate: day(gen.shipDate),
  shipVia: trim(gen.shipVia), instructions: trim(gen.shippingInstructions), notes: trim(gen.internalNotes),
};
const H = v.header || {};
const want = {
  branch: H.shipBranch || cur.branch,
  requiredDate: H.requiredDate || cur.requiredDate,
  shipDate: H.shipDate || cur.shipDate,
  // A blank ship via keeps Eclipse's (there is no known way to clear it).
  shipVia: H.shipVia ? trim(H.shipVia) : cur.shipVia,
  instructions: H.shippingInstructions != null ? trim(H.shippingInstructions) : cur.instructions,
  notes: H.internalNotes != null ? trim(H.internalNotes) : cur.notes,
};
if (want.requiredDate && want.shipDate && want.requiredDate < want.shipDate) return fail(400, 'Required date cannot be before ship date.', 'plan');
if (v.orderStatus && !want.shipVia) return fail(400, 'Pick a ship via before converting the bid to an order.', 'plan');
// Fields the rep changed (sent and different from the open generation).
const edited = {
  shipVia: want.shipVia !== cur.shipVia,
  shipDate: want.shipDate !== cur.shipDate,
  instructions: want.instructions !== cur.instructions,
  notes: want.notes !== cur.notes,
};

// Comments a re-created line keeps: the rep's own (Eclipse commentTypeId
// '1' and '2'; '' is Eclipse's, e.g. "Certification Required", which
// Eclipse adds again itself), without Eclipse's "Requested QTY: n UOM: x"
// note, which it appends on create.
const keepComments = (line) => (Array.isArray(line.comments) ? line.comments : [])
  .filter((c) => ['1', '2'].includes(String(c.commentTypeId)))
  .map((c) => String(c.comment || '').split('\n').filter((s) => !/^\s*Requested QTY:/i.test(s)).join('\n').trim())
  .filter(Boolean);

// Lines on this generation with a quantity.
const genLines = [];
for (const line of (Array.isArray(so.lines) ? so.lines : [])) {
  for (const lg of (Array.isArray(line.generations) ? line.generations : [])) {
    if (String(Number(lg.generationId)) !== v.genId) continue;
    const qty = (Number(lg.stockQty) || 0) + (Number(lg.nonstockQty) || 0);
    if (qty <= 0) continue;
    genLines.push({
      lineId: line.lineId, productId: String(line.productId), qty,
      price: lg.price && lg.price.value != null ? Number(lg.price.value) : null,
      // Line cost and COGS as saved on the order (null when restricted / missing).
      cost: lg.cost && lg.cost.value != null ? Number(lg.cost.value) : null,
      cogs: lg.cogs && lg.cogs.value != null ? Number(lg.cogs.value) : null,
      um: line.displayUom || line.smallestUom || 'ea', umQuantity: Number(line.displayUomQty) || 1,
      description: String(line.productDescription || line.productDecription || '').replace(/\s*\n\s*/g, ' ').trim(),
      lineStatus: String(line.status || ''),
      comments: keepComments(line),
    });
  }
}
const byId = {};
for (const l of genLines) byId[String(l.lineId)] = l;

// Generation refs: 'g:<id>' an existing generation, 'n:<i>' one to create.
const home = 'g:' + v.genId;
const others = so.generations.filter((g) => gidOf(g) !== v.genId && String(g.status) === 'Bid');
const genById = {};
for (const g of so.generations) genById[gidOf(g)] = g;
const refs = {};
const creates = [];
const refFor = (branch) => {
  if (refs[branch]) return refs[branch];
  let ref;
  if (branch === cur.branch && want.requiredDate === cur.requiredDate) ref = home;
  else {
    const hit = others.find((g) => branchOf(g.shipBranch) === branch && day(g.requiredDate) === want.requiredDate);
    if (hit) ref = 'g:' + gidOf(hit);
    else {
      ref = 'n:' + creates.length;
      creates.push({ shipBranch: branch, requiredDate: want.requiredDate, shipDate: want.shipDate, shipStatus: 'Bid' });
    }
  }
  return (refs[branch] = ref);
};

const posts = [], puts = [], prices = [], deletes = [];
// Price changes for price_change_record (2026-10-29): { from, to } on a
// post (new or re-created line), or { lineId, from, to } for a PUT price.
const priceRecords = [];
const differs = (a, b) => a != null && b != null && Math.abs(a - b) >= 0.0005;
const changes = { added: [], qty: [], price: [], deleted: [], moved: [], commented: [], header: [], generations: [], status: null, cancelled: [] };
const kept = new Set();
let homeLive = false;
for (const l of v.lines) {
  const ref = refFor(l.branch || want.branch);
  if (ref === home) homeLive = true;
  if (l.lineId == null) {
    const p = { productId: l.productId, quantity: l.quantity, um: 'ea', umQuantity: 1 };
    if (l.unitPrice != null) p.unitPrice = l.unitPrice;
    if (l.comments) { p.comments = l.comments; p.commentsId = '1'; }
    posts.push({ ref, item: { lineItemProduct: p }, record: !l.custom && differs(l.originalPrice, l.unitPrice) ? { from: l.originalPrice, to: l.unitPrice } : null });
    changes.added.push({ productId: l.productId, quantity: l.quantity, unitPrice: l.unitPrice, custom: !!l.custom, ref });
    continue;
  }
  const c = byId[String(l.lineId)];
  if (!c) return fail(409, 'Line ' + l.lineId + ' is no longer on ' + v.eSorderId + '. Reload the bid and try again.', 'plan');
  if (String(c.productId) !== String(l.productId)) return fail(409, 'Line ' + l.lineId + ' on ' + v.eSorderId + ' is product ' + c.productId + ', not ' + l.productId + '. Reload the bid and try again.', 'plan');
  kept.add(String(l.lineId));
  if (ref !== home || l.comments) {
    // Re-create the line where it belongs, with its comments (plus the new
    // one), qty, unit of measure and price (the bid's, unless changed).
    const notes = c.comments.concat(l.comments ? [l.comments] : []);
    const price = l.unitPrice != null ? l.unitPrice : c.price;
    const p = { productId: Number(c.productId), quantity: l.quantity, um: c.um, umQuantity: c.umQuantity };
    if (price != null) p.unitPrice = price;
    if (notes.length) { p.comments = notes.join('\n'); p.commentsId = '1'; }
    posts.push({ ref, item: { lineItemProduct: p }, record: l.unitPrice != null && differs(c.price, l.unitPrice) ? { from: c.price, to: l.unitPrice } : null });
    deletes.push(c.lineId);
    if (ref !== home) changes.moved.push({ lineId: l.lineId, productId: c.productId, ref });
    else changes.commented.push({ lineId: l.lineId, productId: c.productId, comment: l.comments });
    continue;
  }
  if (l.quantity !== c.qty) {
    puts.push({ lineId: Number(l.lineId), qty: l.quantity, um: c.um });
    changes.qty.push({ lineId: l.lineId, from: c.qty, to: l.quantity });
  }
  if (l.unitPrice != null && (c.price == null || Math.abs(l.unitPrice - c.price) >= 0.0005)) {
    prices.push({ lineId: Number(l.lineId), value: l.unitPrice });
    if (c.price != null) priceRecords.push({ lineId: Number(l.lineId), from: c.price, to: l.unitPrice });
    changes.price.push({ lineId: l.lineId, from: c.price, to: l.unitPrice });
  }
}
for (const l of genLines) {
  if (kept.has(String(l.lineId))) continue;
  deletes.push(l.lineId);
  changes.deleted.push({ lineId: l.lineId, productId: l.productId });
}
// Nothing left on the open generation: its lines are deleted first (the
// DELETE step runs before the cancel), then it is cancelled (2026-10-20, on
// request), so a cancelled generation never keeps the lines that moved.
const cancelHome = !homeLive;
const liveRefs = [...new Set(Object.values(refs))];

// Header: changed fields on every existing generation that ends up with
// lines; a new generation gets the wanted ship via and notes (its dates
// and branch come from Create Shipment).
const headerOps = [];
const fieldOf = { shipVia: 'shipVia', shipDate: 'shipDate', instructions: 'shippingInstructions', notes: 'internalNotes' };
for (const ref of liveRefs) {
  if (ref.startsWith('n:')) {
    for (const k of ['shipVia', 'instructions', 'notes']) if (want[k]) headerOps.push({ ref, kind: k, value: want[k] });
    continue;
  }
  const g = genById[ref.slice(2)];
  for (const k of ['shipVia', 'shipDate', 'instructions', 'notes']) {
    const now = k === 'shipDate' ? day(g.shipDate) : trim(g[fieldOf[k]]);
    if (edited[k] && want[k] !== now) headerOps.push({ ref, kind: k, value: want[k] });
  }
}
for (const k of ['shipVia', 'shipDate', 'instructions', 'notes']) if (edited[k]) changes.header.push({ field: k, from: cur[k], to: want[k] });
if (want.branch !== cur.branch) changes.header.push({ field: 'shipBranch', from: cur.branch, to: want.branch });
if (want.requiredDate !== cur.requiredDate) changes.header.push({ field: 'requiredDate', from: cur.requiredDate, to: want.requiredDate });

// Convert to Order: every generation that keeps lines, plus the order's
// other bid generations.
const statusOps = [];
if (v.orderStatus) {
  const conv = liveRefs.map((ref) => ({ ref, shipDate: want.shipDate }));
  for (const g of others) {
    const ref = 'g:' + gidOf(g);
    if (!liveRefs.includes(ref)) conv.push({ ref, shipDate: day(g.shipDate) });
  }
  for (const x of conv) statusOps.push({ ref: x.ref, status: v.orderStatus, shipDate: x.shipDate });
  changes.status = v.orderStatus;
}

const nothing = !creates.length && !posts.length && !puts.length && !prices.length && !deletes.length &&
  !headerOps.length && !statusOps.length && !cancelHome;
if (nothing) {
  // Nothing to change: answer straight away (ok: false only routes to Respond).
  return [{ json: { ok: false, statusCode: 200, body: { success: true, unchanged: true, e_sorder_id: v.eSorderId, order_id: v.oid } } }];
}
const state = {
  oid: v.oid, home, homeGenId: v.genId, creates, posts, puts, prices,
  deletes,
  headerOps, statusOps, cancelHome, liveRefs, changes, priceRecords,
  // Every line id on the order now, so Price records can tell the lines
  // POST /LineItems adds.
  beforeLineIds: (Array.isArray(so.lines) ? so.lines : []).map((l) => l.lineId),
};
if (!creates.length) return [{ json: { ok: true, create: false, state } }];
return creates.map((c, i) => ({ json: { ok: true, create: true, oid: v.oid, ...c, state: i === 0 ? state : undefined } }));

// The plan with real generation ids (new ones from Create Shipment),
// grouped into the calls each Eclipse step makes.
const state = $('Plan').first().json.state;
const pad = (g) => String(g).padStart(4, '0');
// The new generation's id from a Create Shipment answer. v1 read
// generationId at the top level; a { results: [order] } answer (the shape of
// SO Create) is handled too, taking the highest generation on that branch.
const shipmentGenId = (res, branch) => {
  if (!res || typeof res !== 'object') return '';
  const direct = res.generationId || res.generationID;
  if (direct) return String(Number(direct));
  const r0 = Array.isArray(res.results) ? res.results[0] : null;
  if (!r0) return '';
  if (r0.generationId) return String(Number(r0.generationId));
  const gens = (Array.isArray(r0.generations) ? r0.generations : [])
    .filter((g) => String(g.shipBranch) === String(branch) && String(g.status) !== 'Cancel');
  const ids = gens.map((g) => Number(g.generationId)).filter((n) => n > 0).sort((a, b) => b - a);
  return ids.length ? String(ids[0]) : '';
};
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const shipments = ran('Eclipse: create shipment') ? $('Eclipse: create shipment').all() : [];
const newGen = {};
for (let i = 0; i < state.creates.length; i++) {
  const c = state.creates[i];
  const res = shipments[i] ? shipments[i].json : null;
  const gid = res && !res.error ? shipmentGenId(res, c.shipBranch) : '';
  if (!gid) {
    const why = !res ? 'no response' : res.error ? res.error + ' ' + JSON.stringify(res.message || '').substring(0, 500)
      : 'no generation id in ' + JSON.stringify(res).substring(0, 300);
    return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'createShipment', changes: state.changes,
      error: 'Eclipse could not add a generation for branch ' + c.shipBranch + ' (' + why + '). Nothing else was changed; ' +
        (i ? 'an empty bid generation may have been added. ' : '') + 'reload the bid and try again.' } } }];
  }
  newGen['n:' + i] = gid;
  state.changes.generations.push({ e_sorder_id: state.oid + '.' + pad(gid), ship_branch: c.shipBranch, created: true });
}
const orderIdOf = (ref) => state.oid + '.' + pad(ref.startsWith('g:') ? ref.slice(2) : newGen[ref]);
const homeId = orderIdOf(state.home);

const postGroups = {};
for (const p of state.posts) {
  const id = orderIdOf(p.ref);
  const g = (postGroups[id] = postGroups[id] || { orderId: id, items: [], records: [] });
  g.items.push(p.item);
  g.records.push(p.record || null);
}
const header = (kind) => state.headerOps.filter((o) => o.kind === kind).map((o) => ({ orderId: orderIdOf(o.ref), value: o.value }));
const ops = {
  posts: Object.values(postGroups),
  qty: state.puts.length ? [{ orderId: homeId, items: state.puts }] : [],
  prices: state.prices.length ? [{ orderId: homeId, items: state.prices }] : [],
  deletes: state.deletes.length ? [{ orderId: homeId, lineIds: state.deletes.join(',') }] : [],
  shipVia: header('shipVia'),
  shipDate: header('shipDate'),
  instructions: header('instructions'),
  notes: header('notes'),
  status: state.statusOps.map((s) => ({ orderId: orderIdOf(s.ref), status: s.status, shipDate: s.shipDate })),
  cancels: state.cancelHome ? [{ orderId: homeId }] : [],
};
const has = {};
for (const k of Object.keys(ops)) has[k] = ops[k].length > 0;
if (state.cancelHome) state.changes.cancelled.push(homeId);
// The page reopens on the open generation, or where its lines went.
const live = state.liveRefs.map(orderIdOf);
const openId = state.cancelHome ? live[0] : homeId;
const syncIds = [...new Set([homeId].concat(live, ops.status.map((s) => s.orderId)))];
// For Price records, after the deal sync: PUT prices (home generation) and
// the line ids on the order before the update.
const records = {
  prices: (state.priceRecords || []).map((r) => ({ orderId: homeId, lineId: r.lineId, from: r.from, to: r.to })),
  before: state.beforeLineIds || [],
};
return [{ json: { ok: true, ops, has, changes: state.changes, openId, syncIds, records } }];

const res = $('Resolve').first().json;
let r = $('Trigger HubSpot deal sync').first().json || {};
// A non-JSON content type lands the body in `data` as text; parse it.
if (!r.orders && typeof r.data === 'string') { try { r = JSON.parse(r.data); } catch (e) {} }
// update-hs-deal answers { message, source, orders: [{ <hs_deal_id>: <e_sorder_id> }] }.
const pairs = [];
for (const o of (Array.isArray(r.orders) ? r.orders : [])) {
  for (const [dealId, soId] of Object.entries(o || {})) pairs.push([String(dealId), String(soId)]);
}
const id = res.openId;
const base = (x) => String(x || '').split('.')[0].toUpperCase();
const hit = pairs.find((p) => p[1] === id) || pairs.find((p) => base(p[1]) === base(id)) || (pairs.length === 1 ? pairs[0] : null);
const hubspotSync = r.error ? { ok: false, error: String(r.error) } : { ok: true, orders: r.orders || null };
// price_change_record on the HubSpot line items (Price records).
const pr = $('Price records').first().json;
let priceRecords = { ok: true, sent: pr.count };
if (pr.count) {
  const h = $('HubSpot: price change records').first().json || {};
  if (h.error) priceRecords = { ok: false, sent: pr.count, error: String(h.error) + ' ' + JSON.stringify(h.message || '').substring(0, 300) };
}
return [{ json: { statusCode: 200, body: {
  success: true,
  // The generation to show next: the one that was open, or where its lines
  // went when it was cancelled.
  e_sorder_id: id,
  order_id: id.split('.')[0],
  e_sorder_ids: res.syncIds,
  hs_deal_id: hit ? hit[0] : '',
  changes: res.changes,
  hubspot_sync: hubspotSync,
  price_records: priceRecords,
} } }];

const ops = $('Resolve').first().json.ops.posts;
const out = $input.all();
for (let i = 0; i < out.length; i++) {
  const r = out[i].json;
  if (r.error) {
    const error = 'Eclipse POST /LineItems failed on ' + ((ops[i] || {}).orderId || '?') + ': ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 500);
