// price_change_record on the HubSpot line items whose price the rep changed
// (2026-10-29): "<WRITER>|<old price>|<new price>", e.g. BECCHR|15.00|12.00.
// Runs after the deal sync, which makes the line items; each is found by its
// e_sorder_line_id, "<generation>.<Eclipse line id>" (e.g. S2740887.0001.3).
// A PUT price keeps the line's id. A new or re-created line gets its id from
// the POST /LineItems answer (the whole order, seen in a live run).
const writer = $('Validate').first().json.writer;
const res = $('Resolve').first().json;
const fmt = (n) => {
  const r = Math.round(Number(n) * 10000) / 10000;
  return r.toFixed(Math.max(2, (String(r).split('.')[1] || '').length));
};
const inputs = [];
const add = (orderId, lineId, x) => inputs.push({
  id: orderId + '.' + lineId, idProperty: 'e_sorder_line_id',
  properties: { price_change_record: writer + '|' + fmt(x.from) + '|' + fmt(x.to) },
});
// The lines an add-lines answer (the whole order) has on a generation that
// were not on the order before, in line id order, matched to the posted
// items in turn by product. A posted item with no match is skipped.
const matchPosted = (answer, orderId, items, records, before) => {
  if (!records.some(Boolean)) return;
  const so = answer && !answer.error ? (Array.isArray(answer.results) ? answer.results[0] : answer) : null;
  if (!so || !Array.isArray(so.lines)) return;
  const genId = String(Number(orderId.split('.')[1]));
  const fresh = so.lines
    .filter((l) => !before.has(String(l.lineId)) &&
      (Array.isArray(l.generations) ? l.generations : []).some((g) => String(Number(g.generationId)) === genId))
    .sort((a, b) => Number(a.lineId) - Number(b.lineId));
  let k = 0;
  items.forEach((it, j) => {
    const pid = String(it.lineItemProduct.productId);
    let at = -1;
    for (let i = k; i < fresh.length; i++) if (String(fresh[i].productId) === pid) { at = i; break; }
    if (at < 0) return;
    k = at + 1;
    if (records[j]) add(orderId, fresh[at].lineId, records[j]);
  });
};
for (const p of res.records.prices) add(p.orderId, p.lineId, p);
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const answers = ran('Eclipse: POST /LineItems') ? $('Eclipse: POST /LineItems').all() : [];
const before = new Set(res.records.before.map(String));
res.ops.posts.forEach((g, i) => matchPosted(answers[i] ? answers[i].json : null, g.orderId, g.items, g.records || [], before));
return [{ json: { count: inputs.length, body: { inputs } } }];
